//! Shared fixtures. The values here are typed in by hand from `scripts/gen-hash-vectors.py`; the golden vectors
//! (generated by that independent Python encoder) are what they are compared with.
#![allow(dead_code)]
use journal_types::*;
use serde_json::Value;

pub fn unhex(s: &str) -> Vec<u8> {
    assert!(s.len().is_multiple_of(2));
    (0..s.len() / 2).map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap()).collect()
}

pub fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}

pub fn unhex32(s: &str) -> [u8; 32] {
    unhex(s).try_into().unwrap()
}

pub fn vectors() -> Value {
    serde_json::from_str(include_str!("../vectors.json")).expect("vectors.json parses")
}

pub const PUBKEY_RANGE: [u8; 32] = {
    let mut a = [0u8; 32];
    let mut i = 0;
    while i < 32 {
        a[i] = (i + 1) as u8;
        i += 1;
    }
    a
};

pub const BASE_SEQ: u64 = 0x0102030405060708;

pub fn sha() -> NativeSha256 {
    NativeSha256
}

pub fn feed(source: u8, symbol: &str) -> [u8; 32] {
    feed_id(&sha(), source, symbol)
}

pub fn proof(name: &str) -> PriceProof {
    match name {
        "src2" => PriceProof {
            source: 2,
            feed_id: feed(2, "BTC"),
            timestamp_ns: 1_760_000_000_123_456_789,
            quantized_value: 67_250_123_456_789_012_345_678,
            signed_update: vec![],
        },
        "src3" => PriceProof {
            source: 3,
            feed_id: feed(3, "ETH"),
            timestamp_ns: 1_760_000_100_000_000_001,
            quantized_value: 2_500 * 10i128.pow(18),
            signed_update: (0..40u8).collect(),
        },
        "src4" => PriceProof {
            source: 4,
            feed_id: feed(4, "xyz:AAPL"),
            timestamp_ns: 1_760_000_200_999_999_999,
            quantized_value: 231_450_000_000_000_000_000,
            signed_update: vec![],
        },
        "src255" => PriceProof {
            source: 255,
            feed_id: feed(255, "TEST"),
            timestamp_ns: 0,
            quantized_value: -123_456_789_012_345_678_901_234_567_890,
            signed_update: vec![0xAB; 512],
        },
        other => panic!("unknown proof {other}"),
    }
}

/// proof index 0 and 1 of the chain vectors
pub fn proof_list() -> Vec<PriceProof> {
    vec![proof("src2"), proof("src3")]
}

