/// The same event pointing at no proof.
pub fn without_proof(ev: &JournalEvent) -> JournalEvent {
    let mut e = ev.clone();
    match &mut e {
        JournalEvent::Fill { proof, .. }
        | JournalEvent::Close { proof, .. }
        | JournalEvent::TightStart { proof, .. }
        | JournalEvent::FloorRaised { proof, .. }
        | JournalEvent::Breach { proof, .. }
        | JournalEvent::Fail { proof, .. } => *proof = NO_PROOF,
        _ => {}
    }
    e
}

pub fn genesis() -> [u8; 32] {
    genesis_hash(&sha(), &PUBKEY_RANGE)
}

/// Fill(proof 0), Close(proof 1), Meta; first_seq 1, prev = genesis.
pub fn batch3() -> JournalBatch {
    JournalBatch {
        first_seq: 1,
        prev_hash: genesis(),
        events: vec![event("Fill"), event("Close"), event("Meta")],
        proofs: proof_list(),
    }
}

/// A simple valid batch used by rejection tests.
pub fn small_batch(n_events: usize, n_proofs: usize) -> JournalBatch {
    let proofs: Vec<PriceProof> = (0..n_proofs).map(|_| proof("src2")).collect();
    let events = (0..n_events).map(|i| JournalEvent::TightEnd { time: 1_000 + i as i64 }).collect();
    JournalBatch { first_seq: 1, prev_hash: [7; 32], events, proofs }
}

/// Raw batch bytes built by hand, to craft inputs the encoder refuses to produce.
pub fn raw_batch(first_seq: u64, prev: [u8; 32], events: &[Vec<u8>], n_events_claim: u32, proofs: &[Vec<u8>], n_proofs_claim: u32) -> Vec<u8> {
    let mut v = Vec::new();
    v.extend_from_slice(&first_seq.to_le_bytes());
    v.extend_from_slice(&prev);
    v.extend_from_slice(&n_events_claim.to_le_bytes());
    for e in events {
        v.extend_from_slice(e);
    }
    v.extend_from_slice(&n_proofs_claim.to_le_bytes());
    for p in proofs {
        v.extend_from_slice(p);
    }
    v
}

pub fn tight_end_bytes(time: i64) -> Vec<u8> {
    JournalEvent::TightEnd { time }.to_bytes()
}

/// Raw proof bytes with an arbitrary `signed_update` length prefix and body.
pub fn raw_proof(len_claim: u32, body: &[u8]) -> Vec<u8> {
    let mut v = vec![2u8];
    v.extend_from_slice(&feed(2, "BTC"));
    v.extend_from_slice(&1u64.to_le_bytes());
    v.extend_from_slice(&1i128.to_le_bytes());
    v.extend_from_slice(&len_claim.to_le_bytes());
    v.extend_from_slice(body);
    v
}
